//! Real, explicitly invoked selected-reader lifecycle matrix. No lease issuer.
use super::*;
use crate::modern_lito::{application_protocol as app,transport as tls,protocol,equipment as gear,character_data};
use serde_json::json;
use std::thread;
#[derive(Deserialize)]#[serde(tag="state",deny_unknown_fields)]enum Job{
 RUNNING{source:u32,object:u64,epoch_hex:String},
 COMPLETE{source:u32,object:u64,epoch_hex:String,revision:i64,weapon_object:u64,max_hp:i64,evaluated_at_millis:i64,valid_until_millis:i64},
 REJECTED{source:u32,object:u64,epoch_hex:String,reason:String},
}
fn verify_job(v:&Value,s:Scope,rejected:bool,g:&gear::Snapshot)->Result<bool>{
 let job:Job=serde_json::from_value(v.clone()).map_err(|_|err("fresh_job_schema"))?;
 verify_job_owner(&job,s)?;
 match job{Job::RUNNING{..}=>Ok(false),Job::REJECTED{reason,..}=>{require(rejected&&reason=="ACTUAL_READER_REJECTED","fresh_unexpected_rejection")?;Ok(true)},Job::COMPLETE{revision,weapon_object,max_hp,evaluated_at_millis,valid_until_millis,..}=>{
 let weapon=g.source.items.iter().filter(|i|i.kind==character_data::ItemKind::Weapon&&g.equipped(i.object_id)==Some(true)).map(|i|i.object_id).collect::<Vec<_>>();require(weapon.len()<=1,"ambiguous_actual_weapon")?;
 require(!rejected&&revision==g.revision&&weapon_object==weapon.first().copied().unwrap_or(0)&&max_hp>0,"fresh_complete_revision_weapon_or_time")?;verify_valid_until(evaluated_at_millis,valid_until_millis)?;Ok(true)}}
}
fn verify_valid_until(evaluated:i64,until:i64)->Result<()>{require(evaluated>0&&(until==-1||until>evaluated),"fresh_exclusive_or_permanent_cutoff")}
fn verify_job_owner(job:&Job,s:Scope)->Result<()>{
 let(source,object,epoch)=match &job{Job::RUNNING{source,object,epoch_hex}|Job::COMPLETE{source,object,epoch_hex,..}|Job::REJECTED{source,object,epoch_hex,..}=>(*source,*object,epoch_hex)};
 require(source==s.context.key.source_id&&object==s.context.key.object_id&&epoch==&format!("{:016x}",s.context.epoch),"fresh_job_owner_epoch")?;
 Ok(())
}
fn hold_value(h:&Hold)->Value{json!({"hold_id":h.hold_id,"source":h.source,"object":h.object,"entered":h.entered,"released":h.released,"finished":h.finished,"remaining_nanos_at_entry":h.remaining_nanos_at_entry,"result":h.result,"sql_query_started_epoch_millis":h.sql_query_started_epoch_millis,"sql_cutoff_exclusive_epoch_millis":h.sql_cutoff_exclusive_epoch_millis,"release_at_epoch_millis":h.release_at_epoch_millis,"backend_remaining_nanos_at_release":h.backend_remaining_nanos_at_release})}
struct Matrix{adapter:Adapter,end:Instant,events:Vec<Value>,pending_hold:Option<String>,peers:Vec<Option<tls::ModernTlsConnection>>,opened:u32,closed:u32,hard_dropped:u32,retired:u32}
impl Matrix{
 fn event(&mut self,kind:&str,s:Scope,data:Value){self.events.push(json!({"event":kind,"wall_clock_epoch_millis":now().ok(),"scope":s.safe_value(),"world_match_id":null,"world_generation":null,"private_registration_generation":null,"data":data}));}
 fn command(&mut self,command:&str,args:&[(&str,String)],s:Scope)->Result<Value>{let v=self.adapter.command(command,args,self.end)?;self.event(command,s,json!({"fields":args.iter().map(|(k,v)|((*k).into(),json!(v))).collect::<serde_json::Map<String,Value>>(),"result":v}));Ok(v)}
 fn status(&mut self,s:Scope,label:&str)->Result<Status>{let v=self.adapter.status(self.end)?;self.event(label,s,json!({"provider_calls":v.provider_calls,"hold":v.hold.as_ref().map(hold_value),"jobs":v.jobs,"timer_owned":v.timer_owned}));require(!v.timer_owned,"matrix_must_not_use_SQL_expiry_timer")?;Ok(v)}
 fn fresh_fields(s:Scope,ms:u32)->Vec<(&'static str,String)>{vec![("source_id",s.context.key.source_id.to_string()),("object_id",s.context.key.object_id.to_string()),("epoch_hex",format!("{:016x}",s.context.epoch)),("channel_id",s.channel.to_string()),("deadline_ms",ms.to_string())]}
 fn fresh(&mut self,s:Scope,ms:u32)->Result<String>{let v=self.command("FRESH_READ",&Self::fresh_fields(s,ms),s)?;require(v.as_object().is_some_and(|o|o.len()==1),"fresh_start_shape")?;let id=v["job_id"].as_str().ok_or(err("fresh_job_id"))?;require(uuid(id),"fresh_job_id")?;Ok(id.into())}
 fn wait_job(&mut self,id:&str,s:Scope,rejected:bool,g:&gear::Snapshot)->Result<Value>{let until=(Instant::now()+Duration::from_secs(4)).min(self.end);loop{require(Instant::now()<until,"fresh_job_poll_timeout")?;let status=self.adapter.status(until)?;require(!status.timer_owned,"matrix_expiry_timer_present")?;let v=status.jobs.get(id).ok_or(err("fresh_job_absent"))?;if v["state"]!="RUNNING"{self.event("JOB_TERMINAL_OBSERVED_UNADMITTED",s,json!({"job_id":id,"job":v,"hold":status.hold.as_ref().map(hold_value)}));}if verify_job(v,s,rejected,g)?{let v=v.clone();self.event("JOB_TERMINAL",s,json!({"job_id":id,"provider_calls":status.provider_calls,"job":v,"hold":status.hold.as_ref().map(hold_value),"gear_revision_observed_by_TLS_before_work":g.revision}));return Ok(v);}thread::sleep(Duration::from_millis(20));}}
 fn arm(&mut self,s:Scope)->Result<String>{require(self.pending_hold.is_none(),"matrix_hold_overlap")?;let v=self.command("ARM_HOLD",&[("source_id",s.context.key.source_id.to_string()),("object_id",s.context.key.object_id.to_string())],s)?;let h:Hold=serde_json::from_value(v).map_err(|_|err("hold_schema"))?;require(uuid(&h.hold_id)&&h.source==s.context.key.source_id&&h.object==s.context.key.object_id&&!h.entered&&!h.finished&&!h.released,"hold_arm_owner_state")?;self.pending_hold=Some(h.hold_id.clone());Ok(h.hold_id)}
 fn entered(&mut self,id:&str,s:Scope,before:u32)->Result<Hold>{let until=(Instant::now()+Duration::from_secs(3)).min(self.end);loop{require(Instant::now()<until,"held_SQL_entry_timeout")?;let status=self.adapter.status(until)?;require(!status.timer_owned,"matrix_expiry_timer_present")?;let h=status.hold.ok_or(err("hold_absent"))?;require(h.hold_id==id&&h.source==s.context.key.source_id&&h.object==s.context.key.object_id,"held_SQL_owner")?;if h.entered{require(status.provider_calls==before+1&&h.sql_query_started_epoch_millis>0&&h.remaining_nanos_at_entry>0&&!h.released&&!h.finished&&h.result=="HOLDING_AFTER_REAL_SQL","actual_one_SQL_work_held")?;self.event("REAL_SQL_HOLD_ENTERED",s,json!({"hold":hold_value(&h),"provider_calls_before":before,"provider_calls":status.provider_calls,"only_running_work":status.jobs}));return Ok(h);}thread::sleep(Duration::from_millis(15));}}
 fn release(&mut self,id:&str,s:Scope,timeout:bool)->Result<Hold>{let v=self.command("RELEASE",&[("hold_id",id.into())],s)?;let h:Hold=serde_json::from_value(v).map_err(|_|err("hold_schema"))?;require(h.hold_id==id&&h.source==s.context.key.source_id&&h.object==s.context.key.object_id&&h.entered&&h.released&&h.release_at_epoch_millis>=h.sql_query_started_epoch_millis,"release_owner_or_time")?;require(if timeout{h.finished&&h.result=="REJECTED"&&h.backend_remaining_nanos_at_release<=0}else{h.backend_remaining_nanos_at_release>500_000_000},"release_backend_timeout_distinction")?;self.pending_hold=None;Ok(h)}
 fn old_preSQL(&mut self,s:Scope,g:&gear::Snapshot)->Result<()>{let before=self.status(s,"OLD_READER_BEFORE")?;require(before.jobs.as_object().is_some_and(|jobs|jobs.values().all(|v|v["state"]!="RUNNING")),"preSQL_not_busy_job_rejection")?;
 let guid=unsafe{windows::Win32::System::Com::CoCreateGuid()}.map_err(|_|err("control_request_id"))?;let request=format!("{:08x}-{:04x}-{:04x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",guid.data1,guid.data2,guid.data3,guid.data4[0],guid.data4[1],guid.data4[2],guid.data4[3],guid.data4[4],guid.data4[5],guid.data4[6],guid.data4[7]);
 let fields=Self::fresh_fields(s,8000);let mut body=format!("fixture_id={}\nrequest_id={request}\ncommand=FRESH_READ\n",self.adapter.ready.fixture_id);for(k,v)in &fields{body.push_str(&format!("{k}={v}\n"));}
 #[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Rejected{schema:u32,status:String,reason:String}
 let r:Rejected=decode(&self.adapter.http_expected(Some(&body),self.end,400)?,128*1024)?;require(r.schema==1&&r.status=="REJECTED"&&r.reason=="CONTROL_ARGUMENT_OR_STATE","old_reader_expected_control_rejection")?;
 let after=self.status(s,"OLD_READER_AFTER")?;require(after.provider_calls==before.provider_calls&&after.jobs==before.jobs,"old_reader_not_rejected_before_SQL")?;self.event("OLD_READER_PRE_SQL_REJECTED",s,json!({"request_id":request,"sent_fields":fields.iter().map(|(k,v)|((*k).into(),json!(v))).collect::<serde_json::Map<String,Value>>(),"HTTP":400,"reason":r.reason,"provider_calls_before":before.provider_calls,"provider_calls_after":after.provider_calls,"no_new_job":true,"gear_revision_before_retirement":g.revision,"no_running_job_before_request":true}));Ok(())}
 fn connect(&mut self,p:&runner::Plan,s:Scope)->Result<usize>{let left=self.end.saturating_duration_since(Instant::now());require(left>=Duration::from_millis(50),"matrix_deadline")?;let mut c=tls::connect_and_negotiate(p.endpoint,&p.server_name,Some(&p.ca_der),protocol::Hello{request_id:1,min_version:26,max_version:26,supported_capabilities:runner::CAPS,required_capabilities:runner::CAPS,numeric_schema:1},tls::TransportLimits{connect_timeout:Duration::from_secs(2),total_timeout:left,io_poll_interval:Duration::from_millis(25)},tls::Cancellation::new()).map_err(|_|err("matrix_TLS_connect"))?;self.opened+=1;c.set_exchange_timeout(Duration::from_secs(2)).map_err(|_|err("matrix_TLS_limits"))?;self.peers.push(Some(c));let index=self.peers.len()-1;
 let principal=self.peers[index].as_mut().unwrap().authenticate(app::Credentials::new("3333".into(),"3333".into()).map_err(|_|err("fixture_credentials"))?).map_err(|_|err("matrix_AUTH"))?;require(principal.authorizes_source(s.context.key.source_id),"matrix_source_not_authorized")?;self.event("TLS_AUTH",s,json!({"AUTHraw_captured":false}));Ok(index)}
 fn select(&mut self,index:usize,s:Scope)->Result<gear::Snapshot>{let c=self.peers[index].as_mut().ok_or(err("matrix_peer_closed"))?;c.set_exchange_timeout(self.end.saturating_duration_since(Instant::now()).min(Duration::from_secs(2))).map_err(|_|err("matrix_TLS_limits"))?;let roster=c.characters(s.context.key.source_id,s.context.epoch).map_err(|e|match e{tls::TransportError::CharactersRejected(app::CharacterFailure::BackendUnavailable)=>err("matrix_roster_backend_unavailable"),tls::TransportError::CharactersRejected(app::CharacterFailure::Denied)=>err("matrix_roster_denied"),tls::TransportError::InvalidState(reason)=>Fault{step:"matrix_roster_local_state",code:reason},tls::TransportError::DeadlineExceeded(_)=>err("matrix_roster_timeout"),tls::TransportError::Application(_)=>err("matrix_roster_body_rejected"),tls::TransportError::Io(_)=>err("matrix_roster_IO_or_EOF"),_=>err("matrix_roster_transport_rejected")})?;require(roster.source_id==s.context.key.source_id&&roster.epoch==s.context.epoch&&roster.characters.iter().any(|v|v.key==s.context.key),"matrix_actual_roster")?;let nav=c.select_character(s.context).map_err(|_|err("matrix_select"))?;runner::verify_navigation(&nav,s,app::NavigationPhase::Channels)?;let nav=c.enter_channel(s.channel).map_err(|_|err("matrix_channel"))?;runner::verify_navigation(&nav,s,app::NavigationPhase::Lobby)?;let reply=c.equipment(gear::Request::read(s.context)).map_err(|_|err("matrix_gear"))?;let g=runner::verify_gear(&reply,s)?;self.event("ACTUAL_SELECTED_LOBBY_GEAR",s,json!({"navigation_phase":"Lobby","selected_object":nav.snapshot.selected.as_ref().map(|v|v.key.object_id),"gear_revision":g.revision,"allflags":g.flags.iter().map(|f|json!({"item":f.item_id,"equipped":f.equipped})).collect::<Vec<_>>(),"catalog_generation_hex":g.catalog_generation.iter().map(|b|format!("{b:02x}")).collect::<String>()}));Ok(g)}
 fn back(&mut self,index:usize,s:Scope)->Result<()>{let c=self.peers[index].as_mut().ok_or(err("matrix_peer_closed"))?;let nav=c.return_characters().map_err(|_|err("matrix_BACK"))?;runner::verify_navigation(&nav,s,app::NavigationPhase::Characters)?;self.event("ACTUAL_TLS_BACK",s,json!({"phase":"Characters","selected":null}));Ok(())}
 fn hard_drop(&mut self,index:usize,s:Scope)->Result<()>{let c=self.peers[index].take().ok_or(err("matrix_peer_closed"))?;drop(c);self.hard_dropped+=1;self.retired+=1;self.event("ACTUAL_RUST_SOCKET_DROP",s,json!({"Drop_TCP_Shutdown_Both":true,"TLS_close_notify":false}));Ok(())}
 fn run(&mut self,p:&runner::Plan)->Result<()>{let base=0x8000000000000100;let scope=|source,object,epoch|Scope{context:app::SelectionContext{key:app::CharacterKey{source_id:source,object_id:object},epoch},channel:0};let mut a=scope(7,10275,base);let b=scope(42,10275,base);let ia=self.connect(p,a)?;let ib=self.connect(p,b)?;let mut ga=self.select(ia,a)?;let gb=self.select(ib,b)?;
 for(s,g)in [(a,&ga),(b,&gb)]{let id=self.fresh(s,8000)?;self.wait_job(&id,s,false,g)?;}
 // Cancel the exact registered reader after its real SQL read has entered the hold.
 let before=self.status(a,"BACK_CASE_BEFORE")?.provider_calls;let h=self.arm(a)?;let job=self.fresh(a,8000)?;self.entered(&h,a,before)?;self.back(ia,a)?;self.release(&h,a,false)?;self.wait_job(&job,a,true,&ga)?;self.old_preSQL(a,&ga)?;
 a=scope(7,10163,base+1);ga=self.select(ia,a)?;let id=self.fresh(a,8000)?;self.wait_job(&id,a,false,&ga)?;
 // Reselect while the old 10163/E+1 work is still held; E+2 owns 10275.
 let old=a;let old_gear=ga.clone();let before=self.status(old,"RESELECT_CASE_BEFORE")?.provider_calls;let h=self.arm(old)?;let job=self.fresh(old,8000)?;self.entered(&h,old,before)?;self.back(ia,old)?;a=scope(7,10275,base+2);match self.select(ia,a){Ok(g)=>{ga=g;self.release(&h,old,false)?;self.wait_job(&job,old,true,&old_gear)?;self.old_preSQL(old,&old_gear)?;self.event("OVERLAP_RESELECT_OLD_WORK_REJECTED_AFTER_NEW_OWNER",a,json!({"old_scope":old.safe_value()}));},Err(e)if e.code=="matrix_roster_backend_unavailable"=>{self.event("OVERLAP_RESELECT_ROSTER_BACKEND_UNAVAILABLE",a,json!({"old_scope":old.safe_value(),"actual_TYPED_CHAR_RESULT":"BackendUnavailable","new_owner_admitted":false,"hold_still_pending":h}));self.release(&h,old,false)?;self.wait_job(&job,old,true,&old_gear)?;self.old_preSQL(old,&old_gear)?;ga=self.select(ia,a)?;self.event("SERIAL_RESELECT_AFTER_OLD_WORK_RETIREMENT",a,json!({"old_scope":old.safe_value(),"overlap_reselect_pending_producer_admission":true}));},Err(e)=>return Err(e)}let id=self.fresh(a,8000)?;self.wait_job(&id,a,false,&ga)?;
 // No timer is armed. Wait for the Work's bounded deadline, not SQL expiry.
 let before=self.status(a,"DEADLINE_CASE_BEFORE")?.provider_calls;let h=self.arm(a)?;let observed=Instant::now();let job=self.fresh(a,500)?;let entry=self.entered(&h,a,before)?;let until=(Instant::now()+Duration::from_secs(3)).min(self.end);loop{require(Instant::now()<until,"backend_timeout_not_observed")?;let status=self.adapter.status(until)?;let held=status.hold.ok_or(err("hold_absent"))?;require(held.hold_id==h&&!status.timer_owned,"timeout_hold_or_timer")?;if held.finished{require(held.result=="REJECTED"&&!held.released&&observed.elapsed()>=Duration::from_millis(500),"backend_deadline_not_elapsed")?;self.event("BACKEND_DEADLINE_FINISHED_BEFORE_RELEASE",a,json!({"requested_backend_deadline_ms":500,"entry":hold_value(&entry),"finished":hold_value(&held),"client_observed_elapsed_nanos":observed.elapsed().as_nanos().to_string(),"SQL_expiry_timer_armed":false}));break;}thread::sleep(Duration::from_millis(15));}
 self.release(&h,a,true)?;self.wait_job(&job,a,true,&ga)?;let id=self.fresh(a,8000)?;self.wait_job(&id,a,false,&ga)?;
 let before=self.status(a,"DISCONNECT_CASE_BEFORE")?.provider_calls;let h=self.arm(a)?;let job=self.fresh(a,8000)?;self.entered(&h,a,before)?;self.hard_drop(ia,a)?;thread::sleep(Duration::from_millis(150));self.release(&h,a,false)?;self.wait_job(&job,a,true,&ga)?;self.old_preSQL(a,&ga)?;
 let id=self.fresh(b,8000)?;self.wait_job(&id,b,false,&gb)?;self.back(ib,b)?;self.old_preSQL(b,&gb)?;let final_status=self.status(b,"MATRIX_FINAL_STATUS")?;require(final_status.provider_calls==10&&final_status.jobs.as_object().is_some_and(|v|v.len()==10),"matrix_actual_work_counts")?;Ok(())}
 fn finish(&mut self)->Vec<Fault>{let end=Instant::now()+Duration::from_secs(4);let mut errors=Vec::new();for c in &mut self.peers{if let Some(mut c)=c.take(){if c.close().is_ok(){self.closed+=1;}else{errors.push(err("matrix_TLS_close"));}drop(c);self.retired+=1;}}if let Some(h)=self.pending_hold.take(){if self.adapter.command("RELEASE",&[("hold_id",h)],end).is_err(){errors.push(err("matrix_final_release"));}}if self.adapter.command("TIMER_CLEAR",&[],end).is_err(){errors.push(err("matrix_final_timer_clear"));}if self.adapter.command("SHUTDOWN",&[],end).is_err(){errors.push(err("matrix_shutdown"));}errors}
}
#[test]fn fresh_job_mutants_and_expected_HTTP400_remain_owner_and_status_scoped(){let body=b"HTTP/1.1 400 Bad Request\r\nContent-Length: 2\r\n\r\n{}";assert!(parse_http(body).is_err());assert_eq!(parse_http_expected(body,400).unwrap(),b"{}");assert!(parse_http_expected(b"HTTP/1.1 403 Forbidden\r\nContent-Length: 2\r\n\r\n{}",400).is_err());assert!(parse_http_expected(b"HTTP/1.1 400 Bad Request\r\nContent-Length: 2\r\nContent-length: 2\r\n\r\n{}",400).is_err());let v=json!({"state":"REJECTED","source":7,"object":10275,"epoch_hex":"8000000000000100","reason":"ACTUAL_READER_REJECTED"});assert!(serde_json::from_value::<Job>(v.clone()).is_ok());let s=Scope{context:app::SelectionContext{key:app::CharacterKey{source_id:7,object_id:10275},epoch:0x8000000000000100},channel:0};verify_job_owner(&serde_json::from_value(v.clone()).unwrap(),s).unwrap();for(k,x)in [("source",json!(42)),("object",json!(10163)),("epoch_hex",json!("8000000000000101"))]{let mut mutant=v.clone();mutant[k]=x;assert!(verify_job_owner(&serde_json::from_value(mutant).unwrap(),s).is_err());}verify_valid_until(100,-1).unwrap();verify_valid_until(100,101).unwrap();assert!(verify_valid_until(100,-2).is_err());assert!(verify_valid_until(100,100).is_err());assert!(verify_valid_until(100,99).is_err());let mut bad=v;bad["private_lease"]=json!("invented");assert!(serde_json::from_value::<Job>(bad).is_err());}
#[test]#[ignore="Explicit Modern-owned R37096 fixture READY; distinct lifecycle matrix only"]fn actual_selected_reader_lifecycle_matrix(){
 let path=PathBuf::from(std::env::var("LITO_R442_READY").expect("explicit ready path"));let runtime=path.parent().unwrap();let project=Path::new(env!("CARGO_MANIFEST_DIR"));let snap:Value=serde_json::from_slice(&fs::read(project.join("logs/continuation-20261003/r441b-external-fixture-snapshot.json")).unwrap()).unwrap();let manifest=hash(snap["candidate"]["manifest_sha256"].as_str().unwrap()).unwrap();assert_eq!(manifest,hash("37096A23161C0358786C6039C6BA790278CD1594A111294B9FC6D6AC12FA8E01").unwrap());let(adapter,plan)=Adapter::bind(&path,runtime,manifest,false).expect("strict namespace/identity ready");let mut m=Matrix{adapter,end:Instant::now()+Duration::from_secs(45),events:Vec::new(),pending_hold:None,peers:Vec::new(),opened:0,closed:0,hard_dropped:0,retired:0};let outcome=m.run(&plan);let errors=m.finish();let okay=outcome.is_ok()&&errors.is_empty()&&m.opened==2&&m.closed==1&&m.hard_dropped==1&&m.retired==2;
 let report=json!({"state":if okay{"RUST_SELECTED_READER_MATRIX_PASSED_PENDING_RETIREMENT"}else{"RUST_SELECTED_READER_MATRIX_FAILED"},"fixture_id":m.adapter.ready.fixture_id,"candidate_manifest_sha256":snap["candidate"]["manifest_sha256"],"events":m.events,"failure":outcome.err(),"cleanup_errors":errors,"TLS_opened":m.opened,"TLS_close_notify_completed":m.closed,"TLS_hard_socket_drop":m.hard_dropped,"TLS_sockets_retired":m.retired,"full_recipe_rerun":false,"SQL_expiry_timer_armed":false,"missing_direct_producer_fields":["hold.job_id","hold.selected_epoch_hex","hold.channel_id","hold.private_registration_generation","hold.effective_gear_revision_at_entry","hold.Work_deadline_monotonic_nanos"],"correlation":"single ARM_HOLD consumes sole RUNNING FRESH_READ plus provider count delta1; actual TLS selected scope and full gear revision recorded","renderer_LOADED":false,"GUI":0});fs::write(runtime.join("modern-rust-lifecycle-report.json"),serde_json::to_vec_pretty(&report).unwrap()).unwrap();assert!(okay,"actual lifecycle matrix failed; safe report preserved");
}
